<template><section><div class="head"><h2>后台任务中心</h2><el-button @click="load">刷新</el-button></div><el-table :data="items" v-loading="loading"><el-table-column prop="job_type" label="类型"/><el-table-column prop="resource_id" label="资源" min-width="160"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{row.status}}</el-tag></template></el-table-column><el-table-column label="进度" width="120"><template #default="{row}">{{row.progress_current}} / {{row.progress_total||'-'}}</template></el-table-column><el-table-column prop="attempt" label="尝试" width="70"/><el-table-column prop="error_message" label="失败原因" min-width="180" show-overflow-tooltip/><el-table-column prop="created_at" label="创建时间" width="180"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='failed'||row.status==='cancelled'" link @click="act(row.id,'retry')">重试</el-button><el-button v-if="row.status==='queued'||row.status==='running'" link type="danger" @click="act(row.id,'cancel')">取消</el-button></template></el-table-column></el-table></section></template>
<script setup lang="ts">import{onBeforeUnmount,onMounted,ref}from"vue";import{ElMessage}from"element-plus";import{jobAction,listJobs}from"../api/jobs";import type{BackgroundJobItem}from"../types";const items=ref<BackgroundJobItem[]>([]),loading=ref(false);let timer=0;async function load(){loading.value=true;try{items.value=(await listJobs()).items}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}async function act(id:string,a:"retry"|"cancel"){try{await jobAction(id,a);await load()}catch(e){ElMessage.error((e as Error).message)}}onMounted(()=>{load();timer=window.setInterval(load,2000)});onBeforeUnmount(()=>clearInterval(timer));</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center}</style>
